# ===================================================================
# PayMarket - Corrige le texte invisible + faux toast dans QRCodeGenerator
# ===================================================================

Write-Host "Application du correctif QRCodeGenerator.tsx..." -ForegroundColor Cyan

$b64 = ""
$bytes = [System.Convert]::FromBase64String($b64)
$text = [System.Text.Encoding]::UTF8.GetString($bytes)
[System.IO.File]::WriteAllText("src\components\merchant\QRCodeGenerator.tsx", $text, (New-Object System.Text.UTF8Encoding($false)))
Write-Host "  OK  src\components\merchant\QRCodeGenerator.tsx"

Write-Host ""
Write-Host "Build en cours..." -ForegroundColor Cyan
npm run build

if ($LASTEXITCODE -eq 0) {
  git add -A
  git commit -m "fix: texte invisible dans QRCodeGenerator + suppression du faux toast automatique"
  git push origin main
  Write-Host "Termine et pousse sur GitHub." -ForegroundColor Green
} else {
  Write-Host "Le build a echoue, rien n a ete commit. Copie-moi l erreur ci-dessus." -ForegroundColor Red
}
